begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer)returns uuid language sql immutable as $$select('ae300000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.claim(n integer)returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(n),'session_id',pg_temp.id(n+10),'role','authenticated','user_metadata',jsonb_build_object('operator',true,'security_review','passed','live',true))::text,true)$$;
insert into auth.users(id,email,email_confirmed_at)select pg_temp.id(n),'synthetic-operations-'||n||'@example.test',now()from generate_series(1,3)n;
insert into auth.sessions(id,user_id)select pg_temp.id(n+10),pg_temp.id(n)from generate_series(1,3)n;
insert into public.doctor_profiles(user_id,display_name)values(pg_temp.id(1),'Synthetic operation owner');
insert into public.practices(id,owner_user_id,name)values(pg_temp.id(31),pg_temp.id(1),'Synthetic operation clinic');
insert into public.memberships(id,practice_id,user_id,capabilities)values(pg_temp.id(32),pg_temp.id(31),pg_temp.id(3),array['patients.read']);
insert into public.doctor_saas_terms_versions(id,plan_key,version,status,currency,currency_exponent,monthly_minor,trial_days,staff_limit,staff_unlimited,clinic_limit,clinic_unlimited,over_limit_policy,renewal_policy,grace_days,expiry_policy,cancellation_policy,refund_policy,terms_document_ref,commercial_approval_ref,legal_approval_ref)values
 (pg_temp.id(51),'synthetic-operations',1,'approved','USD',2,1234,2,1,false,1,false,'block_new_allocation','manual',0,'historical_read_only','period_end','manual_review','synthetic-operations/v1','SYNTHETIC_COMMERCIAL','SYNTHETIC_LEGAL');
insert into public.doctor_saas_terms_documents(terms_version_id,document_ref,content_en,content_ar)values(pg_temp.id(51),'synthetic-operations/v1','Synthetic operation document only; not merchant approval.','وثيقة اختبار اصطناعية فقط دون موافقة قانونية.');
update public.doctor_saas_configuration set terms_version_id=pg_temp.id(51),revision=revision+1,change_reason='Owned synthetic redacted diagnostics';
create temporary table results(n integer primary key,quote jsonb,intent jsonb);grant all on results to authenticated;
set local role authenticated;select pg_temp.claim(1);
insert into results(n,quote)select n,public.doctor_create_saas_quote(pg_temp.id(51),2,0,'monthly','synthetic-operations/v1',pg_temp.id(n+60))from generate_series(1,2)n;
update results set intent=public.doctor_prepare_saas_payment((quote->>'quote_id')::uuid,pg_temp.id(n+70));
select public.doctor_submit_privacy_request('access_review',pg_temp.id(81));
select pg_temp.claim(2);
insert into results(n,quote)values(3,public.doctor_create_saas_quote(pg_temp.id(51),2,0,'monthly','synthetic-operations/v1',pg_temp.id(63)));
update results set intent=public.doctor_prepare_saas_payment((quote->>'quote_id')::uuid,pg_temp.id(73))where n=3;
select public.doctor_submit_privacy_request('access_review',pg_temp.id(82));select public.doctor_submit_privacy_request('erasure_review',pg_temp.id(83));
reset role;
select doctor_private.record_saas_synthetic_evidence((select intent->>'intent_id'from results where n=1)::uuid,'synthetic-fixture/operations-unknown',1,'unknown',pg_temp.id(1),1234,'USD',pg_temp.id(91));
select doctor_private.record_saas_synthetic_evidence((select intent->>'intent_id'from results where n=2)::uuid,'synthetic-fixture/operations-mismatch',1,'confirmed',pg_temp.id(2),1,'USD',pg_temp.id(92));
select doctor_private.record_saas_synthetic_evidence((select intent->>'intent_id'from results where n=3)::uuid,'synthetic-fixture/operations-foreign',1,'unknown',pg_temp.id(2),1234,'USD',pg_temp.id(93));
set local role authenticated;select pg_temp.claim(1);
select is(public.doctor_operations_status()->>'subscriber_user_id',pg_temp.id(1)::text,'diagnostics binds fresh subscriber identity');
select is(public.doctor_operations_status()->>'scope','own_saas_operations','scope excludes other practices and patient payloads');
select is(public.doctor_operations_status()#>>'{reconciliation,held_intents}','2','own held-intent population only');
select is(public.doctor_operations_status()#>>'{reconciliation,unknown_review}','1','own unknown outcomes counted without retry authority');
select is(public.doctor_operations_status()#>>'{reconciliation,discrepancy_review}','1','own mismatches remain review signals');
select is(public.doctor_operations_status()#>>'{privacy_intake,awaiting_review}','1','privacy intake count excludes another subscriber');
select is(public.doctor_operations_status()#>>'{privacy_intake,fulfillment_available}','false','diagnostics cannot authorize rights fulfillment');
select is(public.doctor_operations_status()->>'state','diagnostics_only','observed signals are not a healthy or certified badge');
select is(public.doctor_operations_status()->>'independent_security_review','pending','editable metadata cannot approve security');
select is(public.doctor_operations_status()#>>'{security_findings,assessment}','not_performed','missing review is not a zero-finding assessment');
select is(public.doctor_operations_status()#>'{security_findings,critical}','null'::jsonb,'critical findings unknown rather than fabricated zero');
select is(public.doctor_operations_status()#>'{security_findings,high}','null'::jsonb,'high findings unknown rather than fabricated zero');
select is(public.doctor_operations_status()#>'{recovery,rpo}','null'::jsonb,'no invented RPO');
select is(public.doctor_operations_status()#>'{recovery,rto}','null'::jsonb,'no invented RTO');
select is(public.doctor_operations_status()#>>'{recovery,whole_provider_qualified}','false','database restore tests are not whole-provider qualification');
select is(public.doctor_operations_status()#>'{capacity,approved_thresholds}','null'::jsonb,'unapproved thresholds remain null');
select is(public.doctor_operations_status()#>'{capacity,accepted_measurement}','null'::jsonb,'no capacity or hosted load claim');
select is(public.doctor_operations_status()->>'incident_ownership','unconfigured','incident owner is not guessed');
select is(public.doctor_operations_status()->'support_destination','null'::jsonb,'support destination is not guessed');
select is(public.doctor_operations_status()->>'hosted_telemetry_available','false','no invented hosted telemetry');
select is(jsonb_array_length(public.doctor_operations_status()->'launch_decisions'),9,'all nine owner/operator decisions remain open');
select is(public.doctor_operations_status()->>'paid_activation_available','false','diagnostics cannot grant paid access');
select is(public.doctor_operations_status()->>'live_activation','false','metadata cannot enable live admission');
select ok(public.doctor_operations_status()::text not like '%@example.test%','signals include no account email');
select ok(not(public.doctor_operations_status()?'patient_id')and not(public.doctor_operations_status()?'payload')and not(public.doctor_operations_status()?'signature')and not(public.doctor_operations_status()?'endpoint'),'signals omit patient/raw/private protocol detail');
select pg_temp.claim(2);
select is(public.doctor_operations_status()#>>'{reconciliation,held_intents}','1','second subscriber has independent population');
select is(public.doctor_operations_status()#>>'{reconciliation,discrepancy_review}','0','another subscriber does not inherit a mismatch about their reported ID');
select is(public.doctor_operations_status()#>>'{privacy_intake,awaiting_review}','2','second subscriber keeps independent own rights count');
select pg_temp.claim(3);
select throws_ok($$select public.doctor_operations_status()$$,'42501','DOCTOR_OWNER_ENROLLMENT_REQUIRED','delegated practice permission cannot read owner diagnostics');
reset role;
select ok(not has_function_privilege('anon','public.doctor_operations_status()','execute'),'anonymous cannot query diagnostics');
select ok(not has_function_privilege('service_role','public.doctor_operations_status()','execute'),'service role cannot skip subscriber context');
delete from auth.sessions where id=pg_temp.id(11);
set local role authenticated;select pg_temp.claim(1);
select throws_ok($$select public.doctor_operations_status()$$,'42501','DOCTOR_AUTH_REQUIRED','frozen SID cannot read diagnostics');
reset role;
select * from finish();rollback;
